json.dump({'programs': {k: {'years': v[0], 'head': v[1], 'text': v[2], 'images': v[3]} for k, v in PROGRAMS.items()},
           'sites': {k: {'title': v[0], 'text': v[1], 'image': v[2]} for k, v in SITES.items()},
           'facts': [{'head': f[0], 'text': f[1], 'images': f[2]} for f in FACTS],
           'concepts': [{'key': c[0], 'title': c[1], 'diagram': c[2], 'demo': c[3], 'text': c[4]} for c in CONCEPTS]},
          open(os.path.join(d, 'content.json'), 'w', encoding='utf-8'), ensure_ascii=False, indent=0)
print(len(PROGRAMS), 'programs', len(SITES), 'sites', len(FACTS), 'facts', len(CONCEPTS), 'concepts')
